#define FIXED_POINT_SCALE ((1u<<31)-1) // 2^31 for a 32:32 fixed-point format


static void initSineTable( void ) {
	union {
		int32_t    i32;
		uint32_t   u32;
		uint8_t  c8[4];
	} littleEndian32, bigEndian32;
	
	// Precalculate sinewave and convert from little endian to bigendian
	for( int i = 0; i < SAMPLES_PER_CYCLE; i++ ) {
		//littleEndian32.i32 = (int32_t)( sin( i * 2*M_PI / SAMPLES_PER_CYCLE ) * (double)FIXED_POINT_SCALE);
		//printf( "==> %10d\n", (int)littleEndian32.i32 );
		//bigEndian32.c8[ 0 ] = littleEndian32.c8[ 3 ];
		//bigEndian32.c8[ 1 ] = littleEndian32.c8[ 2 ];
		//bigEndian32.c8[ 2 ] = littleEndian32.c8[ 1 ];
		//bigEndian32.c8[ 3 ] = littleEndian32.c8[ 0 ];
		//sine_table[ i ] = bigEndian32.u32;

        //double sintest = sin(i * 2 * M_PI / SAMPLES_PER_CYCLE) + 0.5;
        sine_table[i] = (uint32_t) ( sin( i * 2 * M_PI / SAMPLES_PER_CYCLE ) * (double)FIXED_POINT_SCALE );
        //sine_table[i] = (uint32_t) ( sintest  );

        //sine_table[i] = i * (1<<24);
	}
}


/* Set 1 to allocate rx & tx channels in duplex mode on a same I2S controller, they will share the BCLK and WS signal
 * Set 0 to allocate rx & tx channels in simplex mode, these two channels will be totally separated,
 * Specifically, due to the hardware limitation, the simplex rx & tx channels can't be registered on the same controllers on ESP32 and ESP32-S2,
 * and ESP32-S2 has only one I2S controller, so it can't allocate two simplex channels */


#define EXAMPLE_STD_BCLK_IO1        GPIO_NUM_26     // I2S bit clock io number
#define EXAMPLE_STD_WS_IO1          GPIO_NUM_25      // I2S word select io number
#define EXAMPLE_STD_DOUT_IO1        GPIO_NUM_22     // I2S data out io number
#define EXAMPLE_STD_DIN_IO1         GPIO_NUM_22     // I2S data in io number


static i2s_chan_handle_t                tx_chan;        // I2S tx channel handler

