// Output buffer (2ch interleaved)
static uint16_t out_buf[DMA_BUF_LEN * 2];


static void write_sine()
{
    //uint16_t sinevals[2048];
    //uint32_t tuningWord = pow(2, 32) * 44.0 / 44100.0;



    for(int16_t ii=0;ii < 256; ii++)
    {
        
        int32_t tmp = 0;

        if(mode < 1)
        {
            tmp = (vol * violin[(int32_t) iff] );
            iff += (pluss/500.0f);

            tmp = tmp >> 11;

            if(iff > 128977)
                iff = 0;


        }
        else if(mode < 2)
        {
            tmp = (vol * miau[(int16_t) iff] );
            iff += (pluss/200.0f);

            tmp = tmp >> 11;

            if(iff > 50000)
                iff = 0;

        }
        //phat saw
        else if(mode < 3)
        {
            tmp = (vol * saw[i] + vol * saw[i2]/2 );
            i += (uint16_t) (pluss);
            i2 += (uint16_t) (pluss*1.5);

            tmp = tmp >> 11;
        }
        //soft square
        else if(mode < 4)
        {
            //float vajsing = 1 + (sine65536[tremoloindex])/65536.0f/3.0f;

            tmp = vol * ( softsquare[i] );
            i += (uint16_t) (pluss);
            //i += 200;

            tmp = tmp >> 11;

            //tremoloindex += 1;
        }
        else if(mode < 5)
        {
            tmp = vol * (i > ontime)*16000;
            //tmp += vol * sine65536[tremoloindex];

            i += (uint16_t) (pluss);

            tmp = tmp >> 11;

            //tremoloindex += 2;
        }
        else if(mode < 6)
        {
            tmp = vol * ( saw[i] );
            i += (uint16_t) (pluss);
            //i += 200;

            tmp = tmp >> 11;

        }
        else if(mode < 7)
        {
            tmp = (vol * miau[(int32_t) iff] );
            iff += (pluss/200.0f);

            tmp = tmp >> 11;

            if(iff > 117888)
                iff = 0;

        }


        

        
        output_buffer[ii] =  (int16_t) tmp;
        
        //if(freq < 40)
        //{
        //    targetvol = 0;
        //    iff = 0;
        //}

        if(vol < 150)
            iff = 0;

        
        //i3 += (uint16_t) (pluss*1.75);



        //i += 163;


        //if(i > 32768)
          //i = 0;

        

    }





    //float test = sin(1000 * i);
    //uint16_t test2 = (uint16_t) test;
    //i++;


    //output_buffer[0] = sine16384[i % 128];

    //if(i % 2 == 0)
    
    //vol+=512;

    //vol = 16300;

     //if(freq > 100)
    i2s_channel_write(tx_chan, &output_buffer, 256*2, NULL, 1000);



}



static void write_buffer()
{
    float samp = 0.0f;
    size_t bytes_written;

    for (int i=0; i < DMA_BUF_LEN; i++) {
        // Scale sine sample to 0-1 for internal DAC
        // (can't output negative voltage)
        samp = (sinf(p) + 1.0f) * 0.5f;

        // Increment and wrap phase
        p += PHASE_INC;
        if (p >= TWOPI)
            p -= TWOPI;
        
        // Scale to 8-bit integer range
        samp *= 255.0f;

        // Shift to MSB of 16-bit int for internal DAC
        out_buf[i*2] = out_buf[i*2+1] = (uint16_t)samp << 8;
    }

    // Write with max delay. We want to push buffers as fast as we
    // can into DMA memory. If DMA memory isn't transmitted yet this
    // will yield the task until the interrupt fires when DMA buffer has 
    // space again. If we aren't keeping up with the real-time deadline,
    // audio will glitch and the task will completely consume the CPU,
    // not allowing any task switching interrupts to be processed.
    //i2s_write(I2S_NUM, out_buf, sizeof(out_buf), &bytes_written, portMAX_DELAY);


    bytes_written = sizeof(out_buf);
    
    //i2s_channel_write(tx_handle, src_buf, bytes_to_write, bytes_written, ticks_to_wait);
    i2s_channel_write(tx_chan, out_buf, DMA_BUF_LEN * 2, &bytes_written, 1000);

    // You could put a taskYIELD() here to ensure other tasks always have a chance to run.
    // taskYIELD();
}

