static void i2s_example_write_task(void *args)
{
    //uint8_t *w_buf = (uint8_t *)calloc(1, BUFF_SIZE);
    //uint32_t *w_buf = (uint32_t *)calloc(1, BUFF_SIZE);
    //assert(w_buf); // Check if w_buf allocation success
    static int phase = 0;

/*
    for (int i = 0; i < BUFF_SIZE; i += 8) {
        w_buf[i]     = 0x12;
        w_buf[i + 1] = 0x34;
        w_buf[i + 2] = 0x56;
        w_buf[i + 3] = 0x78;
        w_buf[i + 4] = 0x9A;
        w_buf[i + 5] = 0xBC;
        w_buf[i + 6] = 0xDE;
        w_buf[i + 7] = 0xF0;
    }
*/


    float samp = 0.0f;
    size_t bytes_written;

    for (int i=0; i < DMA_BUF_LEN; i++) {
        // Scale sine sample to 0-1 for internal DAC
        // (can't output negative voltage)
        samp = (sinf(p) + 1.0f) * 0.5f;
        //samp = 0;

        // Increment and wrap phase
        p += PHASE_INC;
        if (p >= TWOPI)
            p -= TWOPI;
        
        // Scale to 8-bit integer range
        samp *= 255.0f;

        // Shift to MSB of 16-bit int for internal DAC
        out_buf[i*2] = out_buf[i*2+1] = (uint16_t)samp << 8;
    }

/*
	for (int i = 0; i < BUFF_SIZE; i += (2 * sizeof( uint32_t))) {
		memcpy( &w_buf[i],   &sine_table[ phase ], sizeof( uint32_t) );
		memcpy( &w_buf[i+sizeof( uint32_t)], &sine_table[ phase ], sizeof( uint32_t) );
		if( ++phase >= SAMPLES_PER_CYCLE)
		    phase = 0;
	}
*/
    size_t w_bytes = BUFF_SIZE;

    /* (Optional) Preload the data before enabling the TX channel, so that the valid data can be transmitted immediately */
    //while (w_bytes == BUFF_SIZE) {
        /* Here we load the target buffer repeatedly, until all the DMA buffers are preloaded */
        //ESP_ERROR_CHECK(i2s_channel_preload_data(tx_chan, w_buf, BUFF_SIZE, &w_bytes));
    //}

    /* Enable the TX channel */
    ESP_ERROR_CHECK(i2s_channel_enable(tx_chan));
    while (1) {
        /* Write i2s data */
        //if (i2s_channel_write(tx_chan, w_buf, BUFF_SIZE, &w_bytes, 1000) == ESP_OK) {
        if (i2s_channel_write(tx_chan, out_buf, sizeof(out_buf), &bytes_written, 1000) == ESP_OK) {
            printf("Write Task: i2s write %d bytes\n", w_bytes);
        } else {
            printf("Write Task: i2s write failed\n");
        }
        //vTaskDelay(pdMS_TO_TICKS(200));
    }
    //free(w_buf);
    vTaskDelete(NULL);
}



static bool alarm_callback(gptimer_handle_t timer, const gptimer_alarm_event_data_t *edata, void *user_ctx)
{
    BaseType_t high_task_awoken = pdFALSE;
    AlarmState = !AlarmState;
    xQueueSendFromISR(StateQueue, &AlarmState, &high_task_awoken);

    vol += 20;

    ESP_ERROR_CHECK(gptimer_enable(gptimer));

    return high_task_awoken == pdTRUE;

}



void timer_callback(void *param)
{
    //targetvol += 100;

    if(targetvol > vol)
            vol+=25;
        else 
            vol-=25;
}



